# Generates Skins\AppMixer\Rows.inc: the pool of app row slots. Rainmeter cannot create meters at runtime,
# so the skin has a fixed number of identical rows that Mixer.lua fills, shows and hides.
# Run it after changing the row layout below, then commit the generated file.
#
# A row, left to right: a gutter (pin button on top, reorder grip below), the app icon, then the name,
# percentage and mute button on top of the volume slider.

$rows = 6
$top = 112     # design y of the first row
$step = 52     # design height of a row

$out = New-Object Text.StringBuilder
[void]$out.AppendLine('; Rows.inc - the pool of app row slots. Mixer.lua fills and shows or hides them.')
[void]$out.AppendLine('; Generated by tools\generate-rows.ps1: the rows are identical except for their number and position.')
[void]$out.AppendLine('')

for ($n = 1; $n -le $rows; $n++) {
    $base = $top + ($n - 1) * $step
    $y = @{ tile = $base + 8; letter = $base + 12; img = $base + 10; name = $base + 4; pct = $base + 4
            slider = $base + 32; hit = $base + 24; mute = $base + 17
            pinGlyph = $base + 12; pinHit = $base + 2; grab = $base + 24 }
    $mouseDown = '$MouseX:%$'
    $row = @"
; ---------- Row $n ----------

[R${n}Tile]
Meter=Shape
MeterStyle=StTile
Y=($($y.tile)*#Scale#)
Shape=Rectangle 0,0,(28*#Scale#),(28*#Scale#),(7*#Scale#) | Fill Color #R${n}Tile# | StrokeWidth 0
Group=R${n}Tile

[R${n}Letter]
Meter=String
MeterStyle=StLetter
Y=($($y.letter)*#Scale#)
Group=R${n}Tile

[R${n}Img]
Meter=Image
MeterStyle=StImg
Y=($($y.img)*#Scale#)
Group=R${n}Img

; Pin button (gutter, top): grey and translucent when the app is not pinned, bright when it is. Mixer.lua sets the color.
[R${n}PinGlyph]
Meter=String
MeterStyle=StPinGlyph
Text=#IconPin#
Y=($($y.pinGlyph)*#Scale#)
Group=R${n}Pin

[R${n}PinHit]
Meter=Shape
MeterStyle=StGutterHit
Y=($($y.pinHit)*#Scale#)
MouseOverAction=[!CommandMeasure Mixer "PinHover($n,1)"]
MouseLeaveAction=[!CommandMeasure Mixer "PinHover($n,0)"]
LeftMouseDownAction=[!CommandMeasure Mixer "Down('pin',$n)"]
LeftMouseUpAction=[!CommandMeasure Mixer "Click('pin',$n)"]
Group=R${n}Pin

; Reorder grip (gutter, below the pin): faint, a little more visible on hover. Dragging it moves the app inside its group.
[R${n}Grab]
Meter=Shape
MeterStyle=StGutterHit
Y=($($y.grab)*#Scale#)
Shape=Rectangle 0,0,(#Gutter#*#Scale#),(16*#Scale#) | Fill Color 0,0,0,1 | StrokeWidth 0
Shape2=Rectangle ((#Gutter#-10)/2*#Scale#),(2*#Scale#),(10*#Scale#),(12*#Scale#),(3*#Scale#) | Fill Color #R${n}Grab# | StrokeWidth 0
MouseOverAction=[!CommandMeasure Mixer "GrabHover($n,1)"]
MouseLeaveAction=[!CommandMeasure Mixer "GrabHover($n,0)"]
LeftMouseDownAction=[!CommandMeasure Mixer "Reorder($n)"]
Group=R${n}Grab

[R${n}Name]
Meter=String
MeterStyle=StName
Y=($($y.name)*#Scale#)
MouseScrollUpAction=[!CommandMeasure Mixer "Wheel($n,1)"]
MouseScrollDownAction=[!CommandMeasure Mixer "Wheel($n,-1)"]
Group=R${n}

[R${n}Percent]
Meter=String
MeterStyle=StPercent
Y=($($y.pct)*#Scale#)
MouseScrollUpAction=[!CommandMeasure Mixer "Wheel($n,1)"]
MouseScrollDownAction=[!CommandMeasure Mixer "Wheel($n,-1)"]
Group=R${n}

[R${n}Slider]
Meter=Shape
MeterStyle=StSlider
Y=($($y.slider)*#Scale#)
Shape=Rectangle 0,0,(208*#Scale#),(6*#Scale#),(3*#Scale#) | Fill Color #R${n}Track# | StrokeWidth 0
Shape2=Rectangle 0,0,(208*#Scale#*#R${n}Vol#/100),(6*#Scale#),(3*#Scale#) | Fill Color #R${n}Fill# | StrokeWidth 0
Shape3=Ellipse (208*#Scale#*#R${n}Vol#/100),(3*#Scale#),(7*#Scale#) | Fill Color #R${n}Thumb# | StrokeWidth 0
Group=R${n}

; Invisible hit area over the track: a press sets the value, the helper then follows the drag.
[R${n}Hit]
Meter=Shape
MeterStyle=StHit
Y=($($y.hit)*#Scale#)
LeftMouseDownAction=[!CommandMeasure Mixer "Press($n,$mouseDown)"]
MouseScrollUpAction=[!CommandMeasure Mixer "Wheel($n,1)"]
MouseScrollDownAction=[!CommandMeasure Mixer "Wheel($n,-1)"]
Group=R${n}Hit

[R${n}Mute]
Meter=String
MeterStyle=StMute
Y=($($y.mute)*#Scale#)
LeftMouseDownAction=[!CommandMeasure Mixer "Down('mute',$n)"]
LeftMouseUpAction=[!CommandMeasure Mixer "Click('mute',$n)"]
MouseLeaveAction=[!CommandMeasure Mixer "Cancel()"]
Group=R${n}


"@
    [void]$out.Append($row)
}

$target = Join-Path (Split-Path -Parent $PSScriptRoot) 'Skins\AppMixer\Rows.inc'
[IO.File]::WriteAllText($target, $out.ToString().TrimEnd() + "`r`n", (New-Object Text.UTF8Encoding $false))
Write-Host "Wrote $target"
